package com.swir.stream;

import android.content.Context;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;
import org.junit.*;
import org.junit.runner.RunWith;
import org.json.JSONObject;
import static org.junit.Assert.*;
import java.io.*;
import java.net.InetAddress;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.atomic.*;
import okhttp3.*;

@RunWith(AndroidJUnit4.class)
public final class SourceExplorerTest {
    private final String base="https://fixture.example";private File root;
    @Before public void setup(){root=new File(InstrumentationRegistry.getInstrumentation().getTargetContext().getCacheDir(),"explorer-"+UUID.randomUUID());assertTrue(root.mkdirs());}
    @After public void cleanup(){remove(root);}
    private static void remove(File file){if(file.isDirectory()){File[] files=file.listFiles();if(files!=null)for(File child:files)remove(child);}file.delete();}
    private static PublicHttp.Document doc(String url,String text){return new PublicHttp.Document(url,text,"text/html",System.currentTimeMillis(),0);}
    private SourceCandidate candidate(String suffix)throws Exception{return new SourceCandidate(base+suffix,"Public TV",base+"/",SourceExplorerRules.Kind.ProviderPage,"Nie potwierdzono",System.currentTimeMillis(),System.currentTimeMillis(),0,0,false);}
    private void rejectAnalyze(PublicHttp.Fetcher fetcher,String url)throws Exception{try{new SourceExplorer(fetcher).analyze(url,null,new AtomicBoolean());fail("Unsafe/invalid document must not produce usable results");}catch(IOException expected){}}
    @Test public void recognizesFourTypesAndNeverFetchesPortalScriptsOrApi()throws Exception{
        List<String> calls=new ArrayList<>();SourceExplorer.Scan scan=new SourceExplorer((url,cancel)->{calls.add(url);if(url.endsWith("/"))return doc(url,"<html><title>Public television</title><a href='/list.m3u'>List</a><a href='/stalker_portal/c/index.html'>Portal</a><a href='/stream.m3u8'>Stream</a><a href='/server/load.php?action=handshake'>No</a></html>");if(url.endsWith("list.m3u"))return doc(url,"#EXTM3U\n#EXTINF:-1,Public TV\nhttps://cdn.example/public.m3u8\n");if(url.endsWith("stream.m3u8"))return doc(url,"#EXTM3U\n#EXT-X-TARGETDURATION:10\n#EXTINF:10,\npublic.ts\n");return doc(url,"<html><title>stalker_portal</title><script src='../server/api/load_js.php'></script><script src='http://192.168.1.13/test.js'></script></html>");}).analyze(base+"/",null,new AtomicBoolean());
        assertEquals(4,scan.candidates.size());Set<SourceExplorerRules.Kind> kinds=new HashSet<>();for(SourceCandidate c:scan.candidates)kinds.add(c.kind);assertEquals(4,kinds.size());assertEquals(4,calls.size());for(String call:calls){assertFalse(call.contains("load.php"));assertFalse(call.endsWith(".js"));}
    }
    @Test public void malformedDashAndCredentialManifestsRejected()throws Exception{for(String body:new String[]{"<MPD><broken","<!DOCTYPE MPD><MPD/>","#EXTM3U\n#EXT-X-STREAM-INF:BANDWIDTH=1\nhttps://cdn.example/live/user/pass/123.m3u8\n","<MPD><BaseURL>https://cdn.example/live/user/pass/123.ts</BaseURL></MPD>"})rejectAnalyze((u,c)->doc(u,body),base+"/stream.mpd");}
    @Test public void protectedDashIsConfigurationCandidateNeverPlayback()throws Exception{SourceExplorer.Scan scan=new SourceExplorer((u,c)->doc(u,"<?xml version='1.0'?>\n<!-- Official public packager comment -->\n<MPD xmlns='urn:mpeg:dash:schema:mpd:2011'><Period><AdaptationSet><ContentProtection schemeIdUri='urn:uuid:test'/></AdaptationSet></Period></MPD>")).analyze(base+"/stream.mpd",null,new AtomicBoolean());assertEquals(1,scan.candidates.size());assertTrue(scan.candidates.get(0).protectedMedia);assertEquals(SourceExplorerRules.Kind.DirectStream,scan.candidates.get(0).kind);}
    @Test public void playlistOldAndFutureDatesCannotReplaceValidResult()throws Exception{String body="#EXTM3U\n#EXTINF:-1,Public TV\nhttps://cdn.example/a.m3u8\n";for(long modified:new long[]{System.currentTimeMillis()-8*86400000L,System.currentTimeMillis()+700000,-1})rejectAnalyze((u,c)->new PublicHttp.Document(u,body,"text/plain",System.currentTimeMillis(),modified),base+"/list.m3u");}
    @Test public void accountListingBodyAndSearchSnippetsAreNotFollowed()throws Exception{AtomicInteger calls=new AtomicInteger();rejectAnalyze((u,c)->{calls.incrementAndGet();return doc(u,"<html><title>TV</title><p>MAC: 00:1A:79:01:02:03 Password&#58; fixture-secret</p><a href='/stalker_portal/c/'>Portal</a></html>");},base+"/");assertEquals(1,calls.get());String rss="<rss><channel><item><title>TV</title><link>https://fixture.example/c/</link><description>Password: fixture-secret</description></item><item><title>Macedonia public playlist</title><link>https://fixture.example/list.m3u</link><description>Public TV</description></item></channel></rss>";assertEquals(1,SourceExplorer.rssHits(rss).size());String duck="<div class='result results_links web-result'><a class='result__a' href='https://fixture.example/c/'>TV</a><a class='result__snippet'>Password: fixture-secret</a></div>";assertTrue(SourceExplorer.duckHits(duck).isEmpty());}
    @Test public void credentialSearchNeverCallsTransport()throws Exception{AtomicInteger calls=new AtomicInteger();for(String query:new String[]{"working MAC list","username%253Du%2526password%253Dfixture","00:1A:79:01:02:03"})try{new SourceExplorer((u,c)->{calls.incrementAndGet();throw new IOException();}).search(query,Collections.emptySet(),null,new AtomicBoolean());fail();}catch(IOException expected){}assertEquals(0,calls.get());assertFalse(SourceExplorer.credentialIndex("Macau TV playlist"));assertFalse(SourceExplorer.credentialIndex("Macedonia public playlist"));}
    @Test public void pageAndDepthLimitsAreEnforced()throws Exception{AtomicInteger calls=new AtomicInteger();SourceExplorer.Scan result=new SourceExplorer((u,c)->{calls.incrementAndGet();StringBuilder html=new StringBuilder("<html><title>Public TV</title>");for(int i=0;i<30;i++)html.append("<a href='/watch/").append(i).append("'>watch</a>");return doc(u,html.append("</html>").toString());}).analyze(base+"/",null,new AtomicBoolean());assertEquals(SourceExplorer.MAX_PAGES,result.pages);assertEquals(12,calls.get());}
    @Test public void perProfileStoreDeduplicatesAndCancellationPreservesBytes()throws Exception{SourceExplorerStore a=new SourceExplorerStore(root,"default"),b=new SourceExplorerStore(root,"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa");SourceCandidate c=candidate("/watch");a.merge(Collections.singletonList(c),new AtomicBoolean());a.merge(Collections.singletonList(c),new AtomicBoolean());assertEquals(1,a.load().size());assertTrue(b.load().isEmpty());File file=new File(root,"default/source-explorer.json");byte[] before=bytes(file);try{a.merge(Collections.singletonList(candidate("/watch2")),new AtomicBoolean(true));fail();}catch(IOException expected){}assertArrayEquals(before,bytes(file));}
    @Test public void corruptOrFutureStoreBlocksOverwriteUntilExplicitReset()throws Exception{SourceExplorerStore store=new SourceExplorerStore(root,"default");store.merge(Collections.singletonList(candidate("/watch")),new AtomicBoolean());File file=new File(root,"default/source-explorer.json");JSONObject json=new JSONObject(new String(bytes(file),StandardCharsets.UTF_8));json.getJSONArray("candidates").getJSONObject(0).put("checkedAt",System.currentTimeMillis()+3600000);try(FileOutputStream out=new FileOutputStream(file)){out.write(json.toString().getBytes(StandardCharsets.UTF_8));}byte[] broken=bytes(file);assertTrue(store.load().isEmpty());assertTrue(store.unreadable());try{store.merge(Collections.singletonList(candidate("/watch2")),new AtomicBoolean());fail();}catch(IOException expected){}assertArrayEquals(broken,bytes(file));store.clear();assertFalse(store.unreadable());assertTrue(store.load().isEmpty());}
    @Test public void candidateRejectsMismatchedIdAndInvalidCounts()throws Exception{JSONObject json=candidate("/watch").json();json.put("id",String.join("",Collections.nCopies(64,"f")));try{SourceCandidate.read(json);fail();}catch(IOException expected){}for(int count:new int[]{-1,100001})try{new SourceCandidate(base+"/watch","TV",base+"/",SourceExplorerRules.Kind.PublicPlaylist,"List",System.currentTimeMillis(),0,0,count,false);fail();}catch(IOException expected){}}
    @Test public void redirectGuardStopsBeforeCredentialOrApiRequest()throws Exception{AtomicInteger sent=new AtomicInteger();OkHttpClient client=new OkHttpClient.Builder().addInterceptor(chain->{sent.incrementAndGet();return new Response.Builder().request(chain.request()).protocol(Protocol.HTTP_1_1).code(302).message("Found").header("Location","/server/load.php?%61ction=handshake&mac=00%3A1A%3A79%3A01%3A02%3A03").body(ResponseBody.create(MediaType.parse("text/plain"),"")).build();}).build();try{new SourceExplorerHttp(client).fetch(base+"/",new AtomicBoolean());fail();}catch(IOException expected){}assertEquals(1,sent.get());}
    @Test public void directSourceUsesVaultReferencesAndReusesId()throws Exception{Context context=InstrumentationRegistry.getInstrumentation().getTargetContext();String profile=UUID.randomUUID().toString().replace("-","");AtomicInteger fetched=new AtomicInteger();ProviderRepository repository=new ProviderRepository(root,profile,(u,h,c)->{fetched.incrementAndGet();throw new IOException();},host->new InetAddress[]{InetAddress.getByAddress(new byte[]{93,(byte)184,(byte)216,34})});try{ProviderRepository.SourceInfo first=repository.addDirect("Public TV",base+"/video.mp4","",new AtomicBoolean());assertEquals(first.id,repository.addDirect("Second",base+"/video.mp4","",new AtomicBoolean()).id);assertEquals(0,fetched.get());Station ref=repository.stations().get(0);assertTrue(ref.url.startsWith("swir://provider/"));assertEquals(base+"/video.mp4",repository.resolve(ref,new AtomicBoolean()).url);assertEquals(1,ProviderManagerDialog.sourcesForSection(repository.listSources(),0).size());}finally{java.security.KeyStore keys=java.security.KeyStore.getInstance("AndroidKeyStore");keys.load(null);keys.deleteEntry("swir.providers.v1."+profile);}}
    @Test public void exactPortalClientNormalizationAndGenericCNotAutoPortal()throws Exception{assertEquals(base+"/stalker_portal/server/load.php",ProviderAdapters.portalEndpoint(base+"/stalker_portal/c/index.html"));assertEquals(SourceLinkParser.Kind.PORTAL,SourceLinkParser.parse(base+"/stalker_portal/c/index.html",false).kind);assertEquals(SourceLinkParser.Kind.M3U,SourceLinkParser.parse(base+"/c/",false).kind);assertEquals(SourceLinkParser.Kind.DIRECT,SourceLinkParser.parse(base+"/movie.mp4",false).kind);}
    @Test public void publishedPlaylistAfter150NavigationLinksAndInsidePreIsFollowed()throws Exception{
        StringBuilder html=new StringBuilder("<html><title>Public television</title>");for(int i=0;i<150;i++)html.append("<a href='/navigation/").append(i).append("'>Help</a>");html.append("<pre><code>https://fixture.example/public-list.m3u</code></pre></html>");List<String> links=SourceExplorerRules.links(base+"/",html.toString());assertEquals(base+"/public-list.m3u",links.get(0));List<String> calls=new ArrayList<>();SourceExplorer.Scan scan=new SourceExplorer((u,c)->{calls.add(u);return doc(u,u.endsWith(".m3u")?"#EXTM3U\n#EXTINF:-1,Public TV\nhttps://cdn.example/one.m3u8\n":html.toString());}).analyze(base+"/",null,new AtomicBoolean());assertTrue(calls.contains(base+"/public-list.m3u"));assertTrue(scan.candidates.stream().anyMatch(r->r.kind==SourceExplorerRules.Kind.PublicPlaylist));assertTrue(scan.pages<=SourceExplorer.MAX_PAGES);
    }
    @Test public void fullSearchQueuePrioritizesPlaylistPublishedByFirstResult()throws Exception{
        AtomicInteger searches=new AtomicInteger();List<String> calls=new ArrayList<>();SourceExplorer.Scan scan=new SourceExplorer((u,c)->{calls.add(u);if(u.contains("bing.com/search")){int offset=searches.getAndIncrement()*10;StringBuilder rss=new StringBuilder("<rss><channel>");for(int i=0;i<10;i++)rss.append("<item><title>Public TV</title><link>https://fixture.example/page/").append(offset+i).append("</link></item>");return doc(u,rss.append("</channel></rss>").toString());}if(u.endsWith(".m3u"))return doc(u,"#EXTM3U\n#EXTINF:-1,Public TV\nhttps://cdn.example/one.m3u8\n");return doc(u,"<html><title>Public TV</title><a href='/published.m3u'>Public list</a></html>");}).search("NASA",Collections.singleton("US"),null,new AtomicBoolean());assertEquals(4,searches.get());assertTrue(calls.contains(base+"/published.m3u"));assertTrue("A published list must outrank waiting information pages",scan.candidates.stream().anyMatch(r->r.kind==SourceExplorerRules.Kind.PublicPlaylist));assertTrue(scan.pages<=SourceExplorer.MAX_PAGES);
    }
    private static byte[] bytes(File file)throws Exception{try(FileInputStream in=new FileInputStream(file);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] block=new byte[8192];int read;while((read=in.read(block))!=-1)out.write(block,0,read);return out.toByteArray();}}
}
